import{c as t,Q as a,j as n,m as o}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"The Untrainable","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-10-@saranormous-400652.md","filePath":"research/tweets/2026-06-10-@saranormous-400652.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-06-10-@saranormous-400652.md"};function r(s,e,h,l,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="the-untrainable" tabindex="-1">The Untrainable <a class="header-anchor" href="#the-untrainable" aria-label="Permalink to &quot;The Untrainable&quot;">​</a></h1><p><strong>作者</strong>：Sarah Guo (@saranormous)<br><strong>發布</strong>：2026-06-10<br><strong>原文</strong>：<a href="https://x.com/saranormous/status/2064510215056400652" target="_blank" rel="noreferrer">https://x.com/saranormous/status/2064510215056400652</a><br><strong>類型</strong>：Twitter Article<br><strong>互動</strong>：👁️ 628,938 views · ❤️ 1,358 · 🔁 106 · 💬 53</p><hr><h2 id="_5維度評分" tabindex="-1">5維度評分 <a class="header-anchor" href="#_5維度評分" aria-label="Permalink to &quot;5維度評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>洞察密度</td><td>5/5</td><td>原創框架（2×2、absorption frontier）密集堆疊，每段都有實質論點</td></tr><tr><td>可操作性</td><td>4/5</td><td>對 AI 創業者與投資人有明確指引；Sierra/Harvey/OpenEvidence 等案例具體</td></tr><tr><td>原創性</td><td>4/5</td><td>「untrainable corner」與「absorption frontier」是新穎的競爭力框架</td></tr><tr><td>論據品質</td><td>4/5</td><td>MIT 大規模研究（10萬開發者）+ 多個現實公司案例佐證</td></tr><tr><td>時效性</td><td>5/5</td><td>2026-06 時間點，直接回應當下 AI 投資人悲觀論</td></tr></tbody></table><p><strong>綜合：4.4 / 5</strong> ⭐⭐⭐⭐½</p><hr><h2 id="核心論點摘要" tabindex="-1">核心論點摘要 <a class="header-anchor" href="#核心論點摘要" aria-label="Permalink to &quot;核心論點摘要&quot;">​</a></h2><p>Sarah Guo 反駁 2026 年 AI 投資人的悲觀論：「模型一直變強，一切都會被吸收，只剩 Anthropic + Nvidia 值得投」。她的論點是：可測量的工作確實正在被吃掉，但有一個「untrainable corner」是模型無法觸及的。</p><h3 id="關鍵數據" tabindex="-1">關鍵數據 <a class="header-anchor" href="#關鍵數據" aria-label="Permalink to &quot;關鍵數據&quot;">​</a></h3><ul><li>MIT 研究（Mert Demirer 等）：10萬+ 開發者樣本，AI coding agent 讓程式碼撰寫量 +180%，但實際 ship 的程式碼只 +30%</li><li>Devin（2024 年）：SWE-bench 13% → 2026 最佳 agent 88%+，但「通過 benchmark ≠ 吃掉軟體工程」</li></ul><h3 id="核心框架-2×2" tabindex="-1">核心框架：2×2 <a class="header-anchor" href="#核心框架-2×2" aria-label="Permalink to &quot;核心框架：2×2&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th><strong>公開答案</strong></th><th><strong>私有答案</strong></th></tr></thead><tbody><tr><td><strong>飽和任務</strong></td><td>商品 token（開源模型主導）</td><td>—</td></tr><tr><td><strong>前沿任務</strong></td><td>Lab 獲勝（有 eval 就能 train）</td><td><strong>Untrainable corner</strong> 🎯</td></tr></tbody></table><p><strong>Untrainable corner</strong> = 前沿工作 × 正確性只存在於私有資料中。</p><h3 id="absorption-frontier-吸收前沿" tabindex="-1">Absorption Frontier（吸收前沿） <a class="header-anchor" href="#absorption-frontier-吸收前沿" aria-label="Permalink to &quot;Absorption Frontier（吸收前沿）&quot;">​</a></h3><ul><li><strong>從下往上</strong>：任務被飽和後變商品 → 最便宜的 open/distilled model 拿走</li><li><strong>從上往下</strong>：Lab 把 scaffolding（retrieval、routing、tool use、reasoning policy）吸收進 weights</li></ul><h3 id="智能不是瓶頸-permission-才是" tabindex="-1">智能不是瓶頸，Permission 才是 <a class="header-anchor" href="#智能不是瓶頸-permission-才是" aria-label="Permalink to &quot;智能不是瓶頸，Permission 才是&quot;">​</a></h3><ul><li>模型更聰明不會讓私有 ground truth 變公開</li><li>不會簽署責任、持有執照、成為訴訟對象</li><li>OpenEvidence：多數美國醫生每天使用，但 Lab 明天訓練出完美醫療模型，也無法進入醫生的決策流程</li></ul><h3 id="護城河的構成" tabindex="-1">護城河的構成 <a class="header-anchor" href="#護城河的構成" aria-label="Permalink to &quot;護城河的構成&quot;">​</a></h3><ol><li><strong>私有性</strong>：公司資料、deals 的形狀（M&amp;A：NDA → term sheet → diligence → 購買協議 → 交割清單）</li><li><strong>不可互換性</strong>：法律領域不同 practice area 的律師與工具不能互換</li><li><strong>定義「好」的權力</strong>：Harvey 出版法律 benchmark；Sierra 定義「resolved」；OpenEvidence 定義安全臨床答案 → 這個權力只能由已在場內的人獲得</li></ol><h3 id="lab-不會競爭你的客戶" tabindex="-1">Lab 不會競爭你的客戶 <a class="header-anchor" href="#lab-不會競爭你的客戶" aria-label="Permalink to &quot;Lab 不會競爭你的客戶&quot;">​</a></h3><ul><li>Consumer chat：更好的模型從未自動獲勝；Gemini 靠 Android + Search 拿份額，非更好的模型</li><li>Anthropic（被認為模型最強）在 consumer chat 幾乎沒影響力，靠 enterprise + coding 建立業務</li></ul><h3 id="攻守兩面" tabindex="-1">攻守兩面 <a class="header-anchor" href="#攻守兩面" aria-label="Permalink to &quot;攻守兩面&quot;">​</a></h3><ul><li><strong>防禦</strong>：在私有資料上 fine-tune → 窄任務打敗通用模型；這個 specialized model 成為護城河的一部分</li><li><strong>進攻</strong>：找到值得建的東西。這件事無法 benchmark，無法 train，「也是為何 incumbents 不能拿走一切」</li></ul><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>The mid-2026 investor&#39;s version of AI psychosis is a despair that nothing is investable, that we should put all our money into Anthropic and Nvidia and go home. I have never felt it. I have been sure the models are smarter than me for several sub-versions now, I&#39;d be a happy buyer of Anthropic and Nvidia at the market price, and all my smartest friends are quite convinced that self-improvement is soon to work – and I still don&#39;t feel it. The despair isn&#39;t stupid. The logic runs: if the model keeps getting better at everything, then every company built on top of one is a thin wrapper waiting to be absorbed, and the only value that survives is the compute and the frontier weights.</p><p>Take software, the case the despair leans on hardest. Devin shipped in 2024 solving thirteen percent of the tasks on the standard software benchmark, and was largely dismissed. A year and a half later the best agents hit the high eighties, and they&#39;re doing real work inside Goldman Sachs and the U.S. Army. Nearly everyone drew the same wrong lesson: the model ate software engineering. But as the model swallowed the part of software engineering you can best measure, we&#39;re relearning what many teams knew – engineering has always resisted measurement, and the most measurable parts may not be the only important ones.</p><p>Mert Demirer and coauthors at MIT finally put numbers on it: across more than 100,000 developers, the latest coding agents lifted how much code got written by roughly 180%, and how much actually shipped by about 30%. Writing got cheap. The rest still runs through a person, and it matters. The net impact is, of course, still amazing.</p><p>A benchmark is a thing you can measure, and a thing you can measure is a thing you can train against. Thus, coding agents matured first: a compiler is a free verifier, a test suite is a free verifier, and when the answer checks itself for nothing you can grind against the check until you beat it. But passing the test never told you the change was the right one for a decade-old codebase with three undocumented reasons that module exists and a deploy pipeline held together by a cron job no one will admit to writing.</p><p>That kind of correctness can&#39;t be read off a leaderboard, and it can&#39;t really be read off anything. You find out whether a system that complex works by running it in the world long enough to learn, and a smarter model doesn&#39;t make the world run faster. Nobody unit-tests something the size of Google and trusts the green check; you trust it because it survived years of real load. Correctness like that isn&#39;t only private, it&#39;s the slow kind of moat capital can&#39;t collapse. Even the optimists grant the clock can&#39;t be skipped: Noam Brown, who has pioneered OpenAI&#39;s reasoning models, wrote recently that the only sure way to evaluate an agent over a one-year horizon may be to run it…for a year.</p><p>As Gabe Pereyra says, real automation isn&#39;t only the model getting better. It&#39;s the product, the model, the workflow, and the firm moving together, and three of those four move at the speed of an organization. Moving people is the part no benchmark touches: getting a skeptical partner to change how she runs her matters, holding a team together through a rebuild. It&#39;s why, when we hire a CEO, the ability to deal with people weighs at least as much as the analytical horsepower, and a smarter model doesn&#39;t change that weighting. The feedback is ambiguous, the horizon is years, and the trust belongs to a person. Every company I know has every engineer on frontier coding models, and not one has changed its eng org at anything close to that speed. Adoption took a quarter, and what a magical quarter of token growth it was! But the rebuild is taking years.</p><p>What&#39;s legible is what&#39;s leaving. The valuable work is illegible by construction: anything you can put on a leaderboard, you can train against, so anything measurable is already on its way to commodity. The process takes time and is never total, but the direction never reverses. Put it in money terms, the way my friend Matt MacInnis at Rippling does: a token spent answering a generic question is worth almost nothing, since anyone&#39;s model can answer it, while a token spent reasoning over your company&#39;s data is worth much more, because it does the thing you actually want, not just the plausible thing.</p><p>The legible work gets eaten from two directions. From below, tasks saturate: once a job can be checked cheaply, the buyer stops asking which model did it and starts asking what it costs, and the work falls to whatever open or distilled model is cheapest that week. Everywhere they can matter, margins eventually matter. From above, the labs are trying to get the models to swallow their own scaffolding. The retrieval, the routing between cheap and expensive calls, the tool use, even the reasoning policy, all the apparatus that used to wrap a model is being pulled into the weights, until the wrapper is the model. This is the absorption frontier. Margin pressure cuts the other way too: a general agent has to be ready for anything, which is expensive, while a focused application can tune one workflow until it runs on a fraction of the token spend, and unlike the lab selling those tokens, it keeps the difference.</p><p>So, we may ask two things of any kind of work. Is its correctness private and expensive to establish, the kind of truth that exists only inside someone&#39;s data? And is it walled off, locked inside a system you can&#39;t get into? Set those against how saturated the task is, and you get a 2x2. Saturated work with public answers is commodity tokens, and open models own it. Frontier work with public answers, where coding benchmarks live, is where the labs win, because when the eval is free, owning it counts for nothing. The prize is the last corner, the untrainable one: frontier work whose correctness exists only in private. You can see it in the inference clouds hosting the AI-native pioneers, where the vast majority of tokens are generated by custom models, not generic open ones.</p><p>The walls into that last corner vary in height. A single developer&#39;s toy codebase is portable and standardized, so the climb is short. A bank&#39;s production systems are neither, and you don&#39;t get root by being 2% more clever on SWE-Bench Verified.</p><p>Capability eats many things, but a better model does not make private ground truth public. It does not hold the license, sign off on the liability, or own the firm&#39;s files, and it cannot be the party that gets sued when the answer is wrong. Intelligence is not the bottleneck here. Permission is, and so is accountability. You can imagine a model far smarter than any person, and it still has to be let in the door, and someone still has to put their name on what it does.</p><p>That door has a lock and a deadbolt. The lock is the environment: you only get to verify whether AI did something useful inside a system once you&#39;re trusted inside it, after the security review, the integration, the contract with your name on the outcome. The deadbolt is the user. A majority of American doctors now open OpenEvidence every day, and no amount of compute buys that. A lab can train a flawless medical model tomorrow and still have no way into the physician&#39;s habit, or into the decision flow of UCSF, because trust is built slowly, on relationships, with user&#39;s acquiescence, not gradient descent that erases them.</p><p>This is also the job. An application earns its place in the untrainable corner by doing unglamorous work: arranging a company&#39;s private reality so a model can act on it, handing the model the tools to act, working with the customer to change the reality of its workforce. A company that brings the translation is tough to copy – and the translation never ends. Integration and maintenance run as long as the relationship does, won by teams that put domain-specialized engineers and tools next to the customer.</p><p>As one example, at a top white-shoe law firm, the M&amp;A practice alone runs close to a thousand deals a year. You can&#39;t have hundreds of associates each downloading client files to a desktop and asking a general agent to rip through them, for confidentiality reasons and a dozen others, and even if you could, what you&#39;d learn would be fragments, one associate&#39;s corrections at a time, with no view of how a whole deal flows. The signal that matters lives at the level of the deal, and a deal has a shape: for M&amp;A the NDA, the term sheet, diligence, the purchase agreement, the ancillaries, the closing checklist; for IP litigation, motions, discovery, prior art, more motions. Each practice area has its own, and neither the lawyers nor the tools interchange across them. And the problem the firm is actually solving sits a level above all of it: running every practice area in parallel, the way a top partner runs hundreds of matters at once while bringing in new ones and training associates. Transforming a firm like that isn&#39;t a single task you can write an eval for. It takes an operator to moneyball it, with extremely ambiguous intermediate goals and incomplete feedback, over very long horizons, in an environment that won&#39;t hold still.</p><p>Illegible value is unfortunately also complicated to sell, for the same reason it&#39;s hard to commoditize: a company can&#39;t tell from the outside whether AI will transform its operations any better than the benchmark can. So the strongest businesses stop trying to prove it externally, get in, and price the outcome instead. Sierra charges when its agent resolves a customer&#39;s issue and nothing when it kicks the problem to a human, so the price becomes the evaluation, and it works only because Sierra owns the definition of resolved. Cognition&#39;s Devin makes the same move in software with a &quot;performance guarantee,&quot; which you can only offer for outcomes in a system you&#39;re trusted inside.</p><p>Even serving tokens, the layer everyone loved to call a pure commodity, doesn&#39;t behave like one. The best AI-native companies concentrate their serving on one or two providers (Baseten or Fireworks) because cost per token commoditizes on schedule while reliability under real traffic and guaranteed access to scarce compute do not. Where you serve is a different choice from which models you use. Price is the only part of inference that acts like a commodity.</p><p>One objection often raised is that the lab is your supplier – why won&#39;t it run its own first-party product below cost to bleed you out, or revoke your API access and take the market itself? That is the real version of the despair, and it only works if the model layer is a single-player game. It clearly isn&#39;t – it looks more like a three-and-a-half-way death match with a crop of international players six months of training behind, and a development league 5X the size it was last year. Customers want competition among their suppliers, and the labs want market share more than they want any one application dead.</p><p>You can watch this in the markets where the labs compete head to head. In consumer chat, the best model has never simply won. ChatGPT held its lead through years of real competition, and the share it is losing now is going to Gemini on the strength of Android and Search, not a better model. Anthropic, which the prediction markets (and internet vibes) currently rate as having the best model, is barely a factor in consumer chat and built its business in enterprise and coding instead. If a better model can&#39;t take a rival&#39;s users in the most central application there is, it isn&#39;t going to integrate its way through a hospital&#39;s records or a bank&#39;s liability. The public chooses on more than coding today. If the frontier remains crowded, the layer above will be valuable.</p><p>If the work can&#39;t be scored from outside, someone on the inside has to decide what a good answer even is, and that decision is the whole game. Enough of those decisions, written down, become a benchmark. Harvey publishes one for law, and Sierra publishes one for voice agents. You earn the right to define what good means for a field by being the one it already uses, and these companies earned that through the struggle of real adoption.</p><p>The evaluation that decides real money is private and per-firm: what this firm, on this kind of matter, will accept as good work, and it is nowhere near finished, because the depth of the law dwarfs any public test. OpenEvidence is settling what a safe clinical answer looks like. None of this is really measurement, it is judgment about what is true and what is good, written down until it becomes the standard everyone else is measured against, and a foundation lab can&#39;t author it however smart it gets, because that standing only exists inside the field. That authority tends to land where it already sat. The senior lawyer writes the legal benchmark. Defining a safe clinical answer falls to a physician. And resolved means whatever the company that already owns the customer says it does.</p><p>The absorption frontier keeps rising, because we keep learning to measure more of the work, and the measurable gets eaten. The untrainable ground shrinks under whoever&#39;s standing on it, so you can&#39;t find a defensible spot and rest. You keep stepping toward whatever can&#39;t yet be scored, and you re-underwrite constantly. On a narrow task, with your private data and your own evals, you can train to the frontier and beat the general models where it counts, and that specialized model becomes part of the moat. On the other hand, competing on the general model is a capital war you lose to whoever owns the most compute, and the trap for a company with shallow access and a legible task. The day it commits to out-training the frontier in a general swath of tasks to survive, the winner seems most decided by datacenter size, and the ending is usually not an independent champion but a sale to someone compute-rich.</p><p>All of that is defense. Even harder is offense, choosing what to build in the first place. That&#39;s what I spend the year looking for, and I find it maybe three times. The model is no help there. It will do whatever you point it at and can&#39;t tell you what&#39;s worth pointing it at, and you can&#39;t benchmark that, so you can&#39;t train it. It&#39;s also the reason the incumbents don&#39;t take everything: they keep the ground they have, and the next thing comes from someone who finds a use before the rest of us. Maybe intent is an even scarcer input than compute.</p><p>The despair is half right. The thin wrapper layer really is being absorbed, and a lot of what looks like a company today is a thin wrapper. It is wrong about what that leaves. The mechanism is clear; the destination isn&#39;t. What I&#39;d bet on is the direction: intelligence keeps getting cheaper, and value keeps sliding toward the few places a model can&#39;t reach. The untrainable is value with history. So get inside one, do the unglamorous translation, and start writing down what good means there, because someone is going to. The most cited benchmark score of the year is a map of territory about to be worthless, and a notice of who is about to lose the right to say what counts as good.</p><p>Also readable on substack.</p><hr><p><em>歸檔時間：2026-06-10</em></p>',52)])])}const p=t(i,[["render",r]]);export{m as __pageData,p as default};
